node -e "
const XLSX = require('xlsx');
const path = 'testbed/data/order_summary.xlsx';
const wb = XLSX.readFile(path);
const ws = wb.Sheets['Orders'];
const data = XLSX.utils.sheet_to_json(ws);

let updated = false;
data.forEach(row => {
  if (row['Order ID'] === 'ORD-6C71B1') {
    row['Status'] = 'confirmed';
    updated = true;
  }
});

if (updated) {
  const newWs = XLSX.utils.json_to_sheet(data);
  wb.Sheets['Orders'] = newWs;
  XLSX.writeFile(wb, path);
  console.log('Updated ORD-6C71B1 status to confirmed.');
} else {
  console.log('Order ORD-6C71B1 not found.');
}
"

